    AND (typeof(NEW.message_trust) = 'text' AND instr(CAST(NEW.message_trust AS BLOB), x'00') = 0 AND length(NEW.message_trust) <= 13 AND length(CAST(NEW.message_trust AS BLOB)) <= 262144)
