WHEN instr(NEW.managed_relative_path, char(92)) > 0
    OR NEW.managed_relative_path = '..'
    OR NEW.managed_relative_path LIKE '%/..'
BEGIN
    SELECT RAISE(ABORT, 'Stored relative paths cannot contain a backslash or a parent segment');
END;

