CREATE TRIGGER sync_capture_chat_working_folder_reference_targets_insert
AFTER INSERT ON chat_working_folder_reference_targets
WHEN (SELECT applying FROM sync_apply_state WHERE singleton = 1) = 0
BEGIN
    INSERT INTO sync_capture (table_id, row_key, mask, created, deleted, captured_at_ms)
    VALUES (378, NEW.reference_id, 1, 1, 0, CAST(unixepoch('subsec') * 1000 AS INTEGER))
    ON CONFLICT (table_id, row_key) DO UPDATE SET
        mask = mask | excluded.mask, created = 1, deleted = 0;
END;

CREATE TRIGGER sync_capture_chat_working_folder_reference_targets_update
AFTER UPDATE ON chat_working_folder_reference_targets
WHEN (SELECT applying FROM sync_apply_state WHERE singleton = 1) = 0
BEGIN
    INSERT INTO sync_capture (table_id, row_key, mask, created, deleted, captured_at_ms)
    SELECT 378, NEW.reference_id, changed.mask, 0, 0, CAST(unixepoch('subsec') * 1000 AS INTEGER)
    FROM (
        SELECT
            0
            AS mask
    ) AS changed
    WHERE changed.mask <> 0
    ON CONFLICT (table_id, row_key) DO UPDATE SET mask = mask | excluded.mask;
END;

CREATE TRIGGER sync_capture_chat_working_folder_reference_targets_delete
AFTER DELETE ON chat_working_folder_reference_targets
WHEN (SELECT applying FROM sync_apply_state WHERE singleton = 1) = 0
BEGIN
    INSERT INTO sync_capture (table_id, row_key, mask, created, deleted, captured_at_ms)
    VALUES (378, OLD.reference_id, 0, 0, 1, CAST(unixepoch('subsec') * 1000 AS INTEGER))
    ON CONFLICT (table_id, row_key) DO UPDATE SET deleted = 1;
END;

CREATE TRIGGER sync_values_chat_workspace_path_reference_targets_insert
BEFORE INSERT ON chat_workspace_path_reference_targets
WHEN ((typeof(NEW.reference_id) = 'text' AND instr(CAST(NEW.reference_id AS BLOB), x'00') = 0 AND trim(NEW.reference_id) <> '' AND length(CAST(NEW.reference_id AS BLOB)) <= 128)
    AND (NEW.working_folder_id IS NULL OR (typeof(NEW.working_folder_id) = 'text' AND instr(CAST(NEW.working_folder_id AS BLOB), x'00') = 0 AND trim(NEW.working_folder_id) <> '' AND length(CAST(NEW.working_folder_id AS BLOB)) <= 128))
    AND (typeof(NEW.path_kind) = 'text' AND instr(CAST(NEW.path_kind AS BLOB), x'00') = 0 AND length(NEW.path_kind) <= 32 AND length(CAST(NEW.path_kind AS BLOB)) <= 262144)
    AND (typeof(NEW.relative_path) = 'text' AND instr(CAST(NEW.relative_path AS BLOB), x'00') = 0 AND length(NEW.relative_path) <= 4096 AND length(CAST(NEW.relative_path AS BLOB)) <= 262144)) IS NOT 1
BEGIN
    SELECT RAISE(ABORT, 'Replicated row values are invalid');
END;

CREATE TRIGGER sync_values_chat_workspace_path_reference_targets_update
BEFORE UPDATE OF working_folder_id, path_kind, relative_path ON chat_workspace_path_reference_targets
WHEN ((NEW.working_folder_id IS NULL OR (typeof(NEW.working_folder_id) = 'text' AND instr(CAST(NEW.working_folder_id AS BLOB), x'00') = 0 AND trim(NEW.working_folder_id) <> '' AND length(CAST(NEW.working_folder_id AS BLOB)) <= 128))
    AND (typeof(NEW.path_kind) = 'text' AND instr(CAST(NEW.path_kind AS BLOB), x'00') = 0 AND length(NEW.path_kind) <= 32 AND length(CAST(NEW.path_kind AS BLOB)) <= 262144)
    AND (typeof(NEW.relative_path) = 'text' AND instr(CAST(NEW.relative_path AS BLOB), x'00') = 0 AND length(NEW.relative_path) <= 4096 AND length(CAST(NEW.relative_path AS BLOB)) <= 262144)) IS NOT 1
BEGIN
    SELECT RAISE(ABORT, 'Replicated row values are invalid');
END;

CREATE TRIGGER sync_immutable_chat_workspace_path_reference_targets
BEFORE UPDATE OF reference_id, working_folder_id, path_kind, relative_path ON chat_workspace_path_reference_targets
WHEN OLD.reference_id IS NOT NEW.reference_id COLLATE BINARY
    OR ((OLD.working_folder_id IS NOT NEW.working_folder_id COLLATE BINARY OR OLD.path_kind IS NOT NEW.path_kind COLLATE BINARY OR OLD.relative_path IS NOT NEW.relative_path COLLATE BINARY) AND (SELECT applying FROM sync_apply_state WHERE singleton = 1) = 0)
BEGIN
    SELECT RAISE(ABORT, 'Replicated row keys and creation times cannot change');
END;

CREATE TRIGGER sync_recreate_chat_workspace_path_reference_targets
BEFORE INSERT ON chat_workspace_path_reference_targets
WHEN (SELECT applying FROM sync_apply_state WHERE singleton = 1) = 0
    AND EXISTS (SELECT 1 FROM sync_rows WHERE table_id = 379 AND row_key = NEW.reference_id)
    AND NOT EXISTS (SELECT 1 FROM chat_workspace_path_reference_targets WHERE reference_id = NEW.reference_id)
BEGIN
    SELECT RAISE(ABORT, 'A published row key cannot be created again');
END;

CREATE TRIGGER sync_capture_chat_workspace_path_reference_targets_insert
AFTER INSERT ON chat_workspace_path_reference_targets
WHEN (SELECT applying FROM sync_apply_state WHERE singleton = 1) = 0
BEGIN
    INSERT INTO sync_capture (table_id, row_key, mask, created, deleted, captured_at_ms)
    VALUES (379, NEW.reference_id, 1, 1, 0, CAST(unixepoch('subsec') * 1000 AS INTEGER))
    ON CONFLICT (table_id, row_key) DO UPDATE SET
        mask = mask | excluded.mask, created = 1, deleted = 0;
END;

CREATE TRIGGER sync_capture_chat_workspace_path_reference_targets_update
AFTER UPDATE ON chat_workspace_path_reference_targets
WHEN (SELECT applying FROM sync_apply_state WHERE singleton = 1) = 0
BEGIN
    INSERT INTO sync_capture (table_id, row_key, mask, created, deleted, captured_at_ms)
    SELECT 379, NEW.reference_id, changed.mask, 0, 0, CAST(unixepoch('subsec') * 1000 AS INTEGER)
    FROM (
        SELECT
            0
            AS mask
    ) AS changed
    WHERE changed.mask <> 0
    ON CONFLICT (table_id, row_key) DO UPDATE SET mask = mask | excluded.mask;
END;

CREATE TRIGGER sync_capture_chat_workspace_path_reference_targets_delete
AFTER DELETE ON chat_workspace_path_reference_targets
WHEN (SELECT applying FROM sync_apply_state WHERE singleton = 1) = 0
BEGIN
    INSERT INTO sync_capture (table_id, row_key, mask, created, deleted, captured_at_ms)
    VALUES (379, OLD.reference_id, 0, 0, 1, CAST(unixepoch('subsec') * 1000 AS INTEGER))
    ON CONFLICT (table_id, row_key) DO UPDATE SET deleted = 1;
END;

-- 12. Sync: Sync clocks, operations, authorization, conflicts, recovery, and seeded row tracking.

CREATE TABLE sync_spaces (
  space_id BLOB PRIMARY KEY NOT NULL CHECK (typeof(space_id) = 'blob' AND length(space_id) = 16),
  vault_id TEXT NOT NULL UNIQUE CHECK (length(vault_id) BETWEEN 1 AND 160),
  created_at_ms INTEGER NOT NULL CHECK (created_at_ms >= 0),
  charter BLOB CHECK (charter IS NULL OR length(charter) >= 1),
  reachable_revision INTEGER NOT NULL DEFAULT 0
    CHECK (reachable_revision >= 0),
  anchor_device_id TEXT
    CHECK (anchor_device_id IS NULL OR length(CAST(anchor_device_id AS BLOB)) BETWEEN 1 AND 160),
  local_device_id TEXT
    CHECK (local_device_id IS NULL OR length(CAST(local_device_id AS BLOB)) BETWEEN 1 AND 160)
) STRICT;

CREATE TABLE sync_anchor_marks (
  space_id BLOB NOT NULL REFERENCES sync_spaces(space_id) ON DELETE CASCADE,
  writer_id BLOB NOT NULL CHECK (length(writer_id) = 16),
  seq INTEGER NOT NULL CHECK (seq >= 1),
  PRIMARY KEY (space_id, writer_id)
) STRICT, WITHOUT ROWID;

CREATE TABLE sync_apply_state (
  singleton INTEGER PRIMARY KEY NOT NULL CHECK (singleton = 1),
  applying INTEGER NOT NULL DEFAULT 0 CHECK (applying IN (0, 1))
) STRICT;

CREATE TABLE sync_auth_envelopes (
  space_id BLOB NOT NULL REFERENCES sync_spaces(space_id) ON DELETE CASCADE,
  role TEXT NOT NULL CHECK (role IN ('record', 'certificate', 'evidence')),
  envelope_hash BLOB NOT NULL CHECK (length(envelope_hash) = 32),
  writer_id BLOB NOT NULL CHECK (length(writer_id) = 16),
  seq INTEGER NOT NULL CHECK (seq >= 1),
  previous_hash BLOB NOT NULL CHECK (length(previous_hash) = 32),
  stamp INTEGER NOT NULL CHECK (stamp >= 0),
  entry_hash BLOB CHECK (entry_hash IS NULL OR length(entry_hash) = 32),
  previous_entry_hash BLOB CHECK (previous_entry_hash IS NULL OR length(previous_entry_hash) = 32),
  device_id TEXT CHECK (device_id IS NULL OR length(CAST(device_id AS BLOB)) BETWEEN 1 AND 160),
  device_key BLOB CHECK (device_key IS NULL OR length(device_key) = 32),
  envelope BLOB NOT NULL,
  verified INTEGER NOT NULL CHECK (verified IN (0, 1)),
  walked INTEGER NOT NULL DEFAULT 0 CHECK (walked IN (0, 1)),
  stored_order INTEGER NOT NULL CHECK (stored_order >= 1),
  stored_at_ms INTEGER NOT NULL CHECK (stored_at_ms >= 0),
  PRIMARY KEY (space_id, role, envelope_hash),
  CHECK ((role = 'record') = (entry_hash IS NOT NULL)),
  CHECK ((role = 'record') = (previous_entry_hash IS NOT NULL)),
  CHECK ((role = 'certificate') = (device_id IS NOT NULL AND device_key IS NOT NULL))
) STRICT, WITHOUT ROWID;
CREATE INDEX idx_sync_auth_envelopes_writer ON sync_auth_envelopes(space_id, writer_id, seq);
CREATE INDEX idx_sync_auth_envelopes_entry ON sync_auth_envelopes(space_id, entry_hash)
    WHERE entry_hash IS NOT NULL;
CREATE INDEX idx_sync_auth_envelopes_hash ON sync_auth_envelopes(space_id, envelope_hash);
CREATE UNIQUE INDEX idx_sync_auth_envelopes_order ON sync_auth_envelopes(space_id, stored_order);
CREATE INDEX idx_sync_auth_envelopes_unwalked ON sync_auth_envelopes(space_id)
    WHERE walked = 0;

CREATE TABLE sync_auth_refetch (
  space_id BLOB NOT NULL REFERENCES sync_spaces(space_id) ON DELETE CASCADE,
  envelope_hash BLOB NOT NULL CHECK (length(envelope_hash) = 32),
  PRIMARY KEY (space_id, envelope_hash)
) STRICT, WITHOUT ROWID;

CREATE TABLE sync_auth_selected (
  space_id BLOB NOT NULL REFERENCES sync_spaces(space_id) ON DELETE CASCADE,
  revision INTEGER NOT NULL CHECK (revision >= 1),
  epoch INTEGER NOT NULL CHECK (epoch BETWEEN 0 AND 4294967295),
  entry_hash BLOB NOT NULL CHECK (length(entry_hash) = 32),
  proposal_hash BLOB NOT NULL CHECK (length(proposal_hash) = 32),
  envelope_hash BLOB NOT NULL CHECK (length(envelope_hash) = 32),
  PRIMARY KEY (space_id, revision)
) STRICT, WITHOUT ROWID;
CREATE INDEX idx_sync_auth_selected_proposal ON sync_auth_selected(space_id, proposal_hash);

CREATE TABLE sync_auth_wanted (
  space_id BLOB NOT NULL REFERENCES sync_spaces(space_id) ON DELETE CASCADE,
  kind TEXT NOT NULL CHECK (kind IN ('entry', 'envelope', 'writer')),
  key BLOB NOT NULL CHECK (length(key) BETWEEN 16 AND 32),
  PRIMARY KEY (space_id, kind, key)
) STRICT, WITHOUT ROWID;

CREATE TABLE sync_capture (
    table_id INTEGER NOT NULL CHECK (table_id BETWEEN 1 AND 65535),
    row_key TEXT NOT NULL CHECK (length(CAST(row_key AS BLOB)) BETWEEN 1 AND 128),
    mask INTEGER NOT NULL,
    forced_mask INTEGER NOT NULL DEFAULT 0,
    created INTEGER NOT NULL CHECK (created IN (0, 1)),
    deleted INTEGER NOT NULL CHECK (deleted IN (0, 1)),
    replaced_by TEXT CHECK (replaced_by IS NULL OR length(CAST(replaced_by AS BLOB)) BETWEEN 1 AND 128),
    captured_at_ms INTEGER NOT NULL CHECK (captured_at_ms >= 0),
    -- A local delete or insert held for Undo until this Unix millisecond time. Sealing skips it
    -- until then, unless a remote change touches the row first.
    held_until_ms INTEGER CHECK (held_until_ms IS NULL OR held_until_ms >= 0),
    PRIMARY KEY (table_id, row_key)
) STRICT, WITHOUT ROWID;

CREATE TABLE sync_devices (
  space_id BLOB NOT NULL REFERENCES sync_spaces(space_id) ON DELETE CASCADE,
  device_id TEXT NOT NULL CHECK (length(CAST(device_id AS BLOB)) BETWEEN 1 AND 160),
  device_key BLOB NOT NULL CHECK (length(device_key) = 32),
  tls_fingerprint BLOB NOT NULL CHECK (length(tls_fingerprint) = 32),
  label TEXT CHECK (label IS NULL OR length(CAST(label AS BLOB)) BETWEEN 1 AND 128),
  kind TEXT NOT NULL CHECK (kind IN ('desktop', 'mobile', 'server')),
  role TEXT NOT NULL CHECK (role IN ('member', 'admin')),
  admin_key BLOB CHECK (admin_key IS NULL OR length(admin_key) = 32),
  enrolled_revision INTEGER NOT NULL CHECK (enrolled_revision >= 0),
  removed_revision INTEGER CHECK (removed_revision IS NULL OR removed_revision > enrolled_revision),
  held INTEGER NOT NULL DEFAULT 0 CHECK (held IN (0, 1)),
  PRIMARY KEY (space_id, device_id),
  CHECK ((role = 'admin') = (admin_key IS NOT NULL)),
  CHECK (role = 'member' OR kind IN ('desktop', 'server'))
) STRICT;

CREATE TABLE sync_displaced_versions (
  table_id INTEGER NOT NULL CHECK (table_id BETWEEN 1 AND 65535),
  row_key TEXT NOT NULL CHECK (length(CAST(row_key AS BLOB)) BETWEEN 1 AND 128),
  group_id INTEGER NOT NULL CHECK (group_id BETWEEN 0 AND 63),
  writer_id BLOB NOT NULL CHECK (length(writer_id) = 16),
  seq INTEGER NOT NULL CHECK (seq >= 1),
  clock INTEGER NOT NULL CHECK (clock >= 0),
  value_hash BLOB NOT NULL CHECK (length(value_hash) = 32),
  value BLOB NOT NULL,
  displaced_by_writer BLOB NOT NULL CHECK (length(displaced_by_writer) = 16),
  displaced_by_seq INTEGER NOT NULL CHECK (displaced_by_seq >= 1),
  PRIMARY KEY (table_id, row_key, group_id, writer_id, displaced_by_writer, displaced_by_seq)
) STRICT, WITHOUT ROWID;
CREATE INDEX idx_sync_displaced_versions_displacer
    ON sync_displaced_versions(displaced_by_writer, displaced_by_seq);

CREATE TABLE sync_fork_evidence (
  space_id BLOB NOT NULL REFERENCES sync_spaces(space_id) ON DELETE CASCADE,
  writer_id BLOB NOT NULL CHECK (length(writer_id) = 16),
  seq INTEGER NOT NULL CHECK (seq >= 1),
  first_envelope BLOB NOT NULL,
  second_envelope BLOB NOT NULL,
  received_at_ms INTEGER NOT NULL CHECK (received_at_ms >= 0),
  settled INTEGER NOT NULL DEFAULT 0
    CHECK (settled IN (0, 1)),
  PRIMARY KEY (space_id, writer_id)
) STRICT;

CREATE TABLE sync_late_changes (
  removal_revision INTEGER NOT NULL CHECK (removal_revision >= 1),
  table_id INTEGER NOT NULL CHECK (table_id BETWEEN 1 AND 65535),
  row_key TEXT NOT NULL CHECK (length(CAST(row_key AS BLOB)) BETWEEN 1 AND 128),
  change TEXT NOT NULL CHECK (change IN ('values', 'tombstone', 'created')),
  mask INTEGER NOT NULL DEFAULT 0,
  groups BLOB,
  resolved_revision INTEGER CHECK (resolved_revision IS NULL OR resolved_revision > removal_revision),
  resolution TEXT
    CHECK (resolution IS NULL OR resolution IN ('restore', 'discard')),
  PRIMARY KEY (removal_revision, table_id, row_key)
) STRICT, WITHOUT ROWID;
CREATE INDEX idx_sync_late_changes_row ON sync_late_changes(table_id, row_key);

CREATE TABLE sync_writers (
  space_id BLOB NOT NULL REFERENCES sync_spaces(space_id) ON DELETE CASCADE,
  writer_id BLOB NOT NULL CHECK (length(writer_id) = 16),
  public_key BLOB NOT NULL UNIQUE CHECK (length(public_key) = 32),
  device_id TEXT NOT NULL CHECK (length(CAST(device_id AS BLOB)) BETWEEN 1 AND 160),
  certificate BLOB NOT NULL,
  state TEXT NOT NULL CHECK (state IN ('active', 'retired', 'revoked', 'forked')),
  predecessor BLOB CHECK (predecessor IS NULL OR length(predecessor) = 16),
  cutoff_seq INTEGER CHECK (cutoff_seq IS NULL OR cutoff_seq >= 0),
  stored_seq INTEGER NOT NULL CHECK (stored_seq >= 1),
  applied_seq INTEGER NOT NULL CHECK (applied_seq >= 0 AND applied_seq <= stored_seq),
  head_hash BLOB NOT NULL CHECK (length(head_hash) = 32),
  head_clock INTEGER NOT NULL CHECK (head_clock >= 0),
  created_at_ms INTEGER NOT NULL CHECK (created_at_ms >= 0),
  compacted_seq INTEGER NOT NULL DEFAULT 0 CHECK (compacted_seq >= 0),
  removal_cutoff_seq INTEGER
    CHECK (removal_cutoff_seq IS NULL OR removal_cutoff_seq >= 0),
  PRIMARY KEY (space_id, writer_id)
) STRICT;

CREATE TABLE sync_ops (
  space_id BLOB NOT NULL,
  writer_id BLOB NOT NULL,
  seq INTEGER NOT NULL CHECK (seq >= 1),
  kind INTEGER NOT NULL CHECK (kind BETWEEN 0 AND 255),
  hash BLOB NOT NULL CHECK (length(hash) = 32),
  clock INTEGER NOT NULL CHECK (clock >= 0),
  context BLOB NOT NULL,
  envelope BLOB NOT NULL CHECK (length(envelope) <= 524288),
  state TEXT NOT NULL CHECK (state IN ('waiting', 'applied', 'held')),
  hold_reason TEXT CHECK (hold_reason IN ('newer_format', 'newer_manifest', 'invalid')),
  stored_at_ms INTEGER NOT NULL CHECK (stored_at_ms >= 0),
  authorization_revision INTEGER NOT NULL DEFAULT 0
    CHECK (authorization_revision >= 0),
  excluded_revision INTEGER
    CHECK (excluded_revision IS NULL OR excluded_revision >= 1),
  group_continues INTEGER NOT NULL DEFAULT 0
    CHECK (group_continues IN (0, 1)),
  stored_order INTEGER NOT NULL DEFAULT 0
    CHECK (stored_order >= 0),
  PRIMARY KEY (space_id, writer_id, seq),
  FOREIGN KEY (space_id, writer_id) REFERENCES sync_writers(space_id, writer_id) ON DELETE CASCADE,
  CHECK ((state = 'held') = (hold_reason IS NOT NULL))
) STRICT;
CREATE INDEX idx_sync_ops_pending ON sync_ops(state, space_id, writer_id, seq)
    WHERE state <> 'applied';
CREATE INDEX idx_sync_ops_excluded ON sync_ops(space_id, excluded_revision, writer_id, seq)
    WHERE excluded_revision IS NOT NULL;
CREATE INDEX idx_sync_ops_chain_ends ON sync_ops(space_id, writer_id, seq)
    WHERE group_continues = 0;
CREATE INDEX idx_sync_ops_stored_order ON sync_ops(space_id, stored_order);

CREATE TABLE sync_recovery_kit (
  id INTEGER PRIMARY KEY CHECK (id = 1),
  recovery_admin_key BLOB NOT NULL CHECK (length(recovery_admin_key) = 32),
  recovery_encryption_key BLOB NOT NULL CHECK (length(recovery_encryption_key) = 32),
  created_at_ms INTEGER NOT NULL CHECK (created_at_ms >= 0)
) STRICT;

CREATE TABLE sync_rows (
  table_id INTEGER NOT NULL CHECK (table_id BETWEEN 1 AND 65535),
  row_key TEXT NOT NULL CHECK (length(CAST(row_key AS BLOB)) BETWEEN 1 AND 128),
  state TEXT NOT NULL CHECK (state IN ('live', 'tombstoned')),
  recovery INTEGER NOT NULL DEFAULT 0 CHECK (recovery IN (0, 1) AND (recovery = 0 OR state = 'tombstoned')),
  conflict_mask INTEGER NOT NULL DEFAULT 0 CHECK (conflict_mask = 0 OR state = 'live'),
  creation_pending INTEGER NOT NULL DEFAULT 0
    CHECK (creation_pending IN (0, 1)),
  PRIMARY KEY (table_id, row_key)
) STRICT, WITHOUT ROWID;
CREATE INDEX idx_sync_rows_recovery ON sync_rows(table_id, row_key) WHERE recovery = 1;
CREATE INDEX idx_sync_rows_conflicts ON sync_rows(table_id, row_key) WHERE conflict_mask <> 0;

CREATE TABLE sync_register_versions (
  table_id INTEGER NOT NULL,
  row_key TEXT NOT NULL,
  group_id INTEGER NOT NULL CHECK (group_id BETWEEN 0 AND 63),
  writer_id BLOB NOT NULL CHECK (length(writer_id) = 16),
  seq INTEGER NOT NULL CHECK (seq >= 1),
  clock INTEGER NOT NULL CHECK (clock >= 0),
  value_hash BLOB NOT NULL CHECK (length(value_hash) = 32),
  value BLOB,
  PRIMARY KEY (table_id, row_key, group_id, writer_id),
  FOREIGN KEY (table_id, row_key) REFERENCES sync_rows(table_id, row_key) ON DELETE CASCADE
) STRICT, WITHOUT ROWID;

CREATE TABLE sync_released_marks (
  space_id BLOB NOT NULL REFERENCES sync_spaces(space_id) ON DELETE CASCADE,
  writer_id BLOB NOT NULL CHECK (length(writer_id) = 16),
  seq INTEGER NOT NULL CHECK (seq >= 1),
  PRIMARY KEY (space_id, writer_id)
) STRICT, WITHOUT ROWID;

CREATE TABLE sync_restated_groups (
  table_id INTEGER NOT NULL CHECK (table_id BETWEEN 1 AND 65535),
  row_key TEXT NOT NULL CHECK (length(CAST(row_key AS BLOB)) BETWEEN 1 AND 128),
  group_id INTEGER NOT NULL CHECK (group_id BETWEEN 0 AND 63),
  value_hash BLOB NOT NULL CHECK (length(value_hash) = 32),
  PRIMARY KEY (table_id, row_key, group_id)
) STRICT, WITHOUT ROWID;

CREATE TABLE sync_row_creations (
  table_id INTEGER NOT NULL,
  row_key TEXT NOT NULL,
  writer_id BLOB NOT NULL CHECK (length(writer_id) = 16),
  seq INTEGER NOT NULL CHECK (seq >= 1),
  PRIMARY KEY (table_id, row_key, writer_id, seq),
  FOREIGN KEY (table_id, row_key) REFERENCES sync_rows(table_id, row_key) ON DELETE CASCADE
) STRICT, WITHOUT ROWID;
CREATE INDEX idx_sync_row_creations_writer ON sync_row_creations(writer_id, seq);

CREATE TABLE sync_seeded_tables (
  table_id INTEGER PRIMARY KEY CHECK (table_id BETWEEN 1 AND 65535)
) STRICT;

CREATE TABLE sync_space_keys (
  space_id BLOB NOT NULL REFERENCES sync_spaces(space_id) ON DELETE CASCADE,
  epoch INTEGER NOT NULL CHECK (epoch >= 1 AND epoch <= 4294967295),
  wrapped_previous BLOB CHECK (wrapped_previous IS NULL OR length(wrapped_previous) = 72),
  own_envelope BLOB CHECK (own_envelope IS NULL OR length(own_envelope) = 96),
  sequenced_revision INTEGER NOT NULL CHECK (sequenced_revision >= 1),
  CHECK ((epoch = 1) = (wrapped_previous IS NULL)),
  PRIMARY KEY (space_id, epoch)
) STRICT, WITHOUT ROWID;

CREATE TABLE sync_stable (
  space_id BLOB NOT NULL REFERENCES sync_spaces(space_id) ON DELETE CASCADE,
  writer_id BLOB NOT NULL CHECK (length(writer_id) = 16),
  seq INTEGER NOT NULL CHECK (seq >= 1),
  PRIMARY KEY (space_id, writer_id)
) STRICT, WITHOUT ROWID;

CREATE TABLE sync_stale_rows (
  table_id INTEGER NOT NULL CHECK (table_id BETWEEN 1 AND 65535),
  row_key TEXT NOT NULL CHECK (length(CAST(row_key AS BLOB)) BETWEEN 1 AND 128),
  PRIMARY KEY (table_id, row_key)
) STRICT, WITHOUT ROWID;

CREATE TABLE sync_tombstones (
  table_id INTEGER NOT NULL,
  row_key TEXT NOT NULL,
  writer_id BLOB NOT NULL CHECK (length(writer_id) = 16),
  seq INTEGER NOT NULL CHECK (seq >= 1),
  replaced_by TEXT CHECK (replaced_by IS NULL OR replaced_by < row_key),
  cause_table INTEGER
    CHECK (cause_table IS NULL OR (cause_table BETWEEN 1 AND 65535 AND replaced_by IS NULL)),
  cause_row TEXT
    CHECK ((cause_row IS NULL) = (cause_table IS NULL)
        AND (cause_row IS NULL OR length(CAST(cause_row AS BLOB)) BETWEEN 1 AND 128)),
  PRIMARY KEY (table_id, row_key, writer_id, seq),
  FOREIGN KEY (table_id, row_key) REFERENCES sync_rows(table_id, row_key) ON DELETE CASCADE
) STRICT, WITHOUT ROWID;
CREATE INDEX idx_sync_tombstones_redirect ON sync_tombstones(table_id, replaced_by)
    WHERE replaced_by IS NOT NULL;
CREATE INDEX idx_sync_tombstones_cause ON sync_tombstones(cause_table, cause_row)
    WHERE cause_table IS NOT NULL;

CREATE TABLE sync_version_refs (
  table_id INTEGER NOT NULL,
  row_key TEXT NOT NULL,
  group_id INTEGER NOT NULL,
  writer_id BLOB NOT NULL,
  field INTEGER NOT NULL CHECK (field BETWEEN 0 AND 255),
  ref_key TEXT NOT NULL CHECK (length(CAST(ref_key AS BLOB)) BETWEEN 1 AND 128),
  PRIMARY KEY (table_id, row_key, group_id, writer_id, field, ref_key),
  FOREIGN KEY (table_id, row_key, group_id, writer_id)
      REFERENCES sync_register_versions(table_id, row_key, group_id, writer_id)
      ON DELETE CASCADE
) STRICT, WITHOUT ROWID;
CREATE INDEX idx_sync_version_refs_key ON sync_version_refs(ref_key);

-- Sync seed rows.

INSERT INTO sync_apply_state (singleton, applying) VALUES
  (1, 0);

INSERT INTO sync_seeded_tables (table_id) VALUES
  (1),
  (2);
